TLM.f("Tempora/Pasc7-4",{"officium":"Die Quinta infra octavam Pentecostes","rule":["Gloria","Sequentia","Credo","Prefatio=Spiritu=hodierna die;"],"ruleInherited":["Gloria","Sequentia","Credo","Prefatio=Spiritu=hodierna die;"],"fallback":"Tempora/Pasc7-0","sections":{"Introitus":[{"k":"ref","la":"Sap 1:7"},{"k":"text","la":"Spíritus Dómini replévit orbem terrárum, allelúja: et hoc quod cóntinet ómnia, sciéntiam habet vocis, allelúja, allelúja, allelúja."},{"k":"ref","la":"Ps 67:2"},{"k":"text","la":"Exsúrgat Deus, et dissipéntur inimíci ejus: et fúgiant, qui odérunt eum, a fácie ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Spíritus Dómini replévit orbem terrárum, allelúja: et hoc quod cóntinet ómnia, sciéntiam habet vocis, allelúja, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Deus, qui hodiérna die corda fidélium Sancti Spíritus illustratióne docuísti: da nobis in eódem Spíritu recta sápere; et de ejus semper consolatióne gaudére."},{"k":"macro","name":"Per Dominum eiusdem"}],"Lectio":[{"k":"text","la":"Léctio Actuum Apostolórum"},{"k":"ref","la":"Acts 8:5-8"},{"k":"text","la":"In diébus illis: Philíppus descéndens in civitátem Samaríæ, prædicábat illis Christum. Intendébant autem turbæ his, quæ a Philíppo dicebántur, unanímiter audiéntes et vidéntes signa, quæ faciébat. Multi enim eórum, qui habébant spíritus immúndos, clamántes voce magna, exíbant. Multi autem paralýtici et claudi curáti sunt. Factum est ergo gáudium magnum in illa civitáte."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 103:30"},{"k":"text","la":"Emítte Spíritum tuum, et creabúntur, et renovábis fáciem terræ. Allelúja. (Hic genuflectitur)","mark":"V"},{"k":"text","la":"Veni, Sancte Spíritus, reple tuórum corda fidélium: et tui amóris in eis ignem accénde.","mark":"V"}],"Sequentia":[{"k":"text","la":"Veni, Sancte Spíritus,"},{"k":"text","la":"et emítte cǽlitus"},{"k":"text","la":"lucis tuæ rádium."},{"k":"sep"},{"k":"text","la":"Veni, pater páuperum;"},{"k":"text","la":"veni, dator múnerum;"},{"k":"text","la":"veni, lumen córdium."},{"k":"sep"},{"k":"text","la":"Consolátor óptime,"},{"k":"text","la":"dulcis hospes ánimæ,"},{"k":"text","la":"dulce refrigérium."},{"k":"sep"},{"k":"text","la":"In labóre réquies,"},{"k":"text","la":"in æstu tempéries,"},{"k":"text","la":"in fletu solácium."},{"k":"sep"},{"k":"text","la":"O lux beatíssima,"},{"k":"text","la":"reple cordis íntima"},{"k":"text","la":"tuórum fidélium."},{"k":"sep"},{"k":"text","la":"Sine tuo númine"},{"k":"text","la":"nihil est in hómine,"},{"k":"text","la":"nihil est innóxium."},{"k":"sep"},{"k":"text","la":"Lava quod est sórdidum,"},{"k":"text","la":"riga quod est áridum,"},{"k":"text","la":"sana quod est sáucium."},{"k":"sep"},{"k":"text","la":"Flecte quod est rígidum,"},{"k":"text","la":"fove quod est frígidum,"},{"k":"text","la":"rege quod est dévium."},{"k":"sep"},{"k":"text","la":"Da tuis fidélibus,"},{"k":"text","la":"in te confidéntibus,"},{"k":"text","la":"sacrum septenárium."},{"k":"sep"},{"k":"text","la":"Da virtútis méritum,"},{"k":"text","la":"da salútis éxitum,"},{"k":"text","la":"da perénne gáudium."},{"k":"text","la":"Amen. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 9:1-6"},{"k":"text","la":"In illo témpore: Convocátis Jesus duódecim Apóstolis, dedit illis virtútem et potestátem super ómnia dæmónia, et ut languóres curárent. Et misit illos prædicáre regnum Dei et sanáre infírmos. Et ait ad illos: Nihil tuléritis in via, neque virgam, neque peram, neque panem, neque pecúniam, neque duas túnicas habeátis. Et in quamcúmque domum intravéritis, ibi manéte et inde ne exeátis. Et quicúmque non recéperint vos: exeúntes de civitáte illa, étiam púlverem pedum vestrórum excútite in testimónium supra illos. Egréssi autem circuíbant per castélla, evangelizántes et curántes ubíque."}],"Offertorium":[{"k":"ref","la":"Ps 67:29-30"},{"k":"text","la":"Confírma hoc, Deus, quod operátus es in nobis: a templo tuo, quod est in Jerúsalem, tibi ófferent reges múnera, allelúja."}],"Secreta":[{"k":"text","la":"Múnera, quǽsumus, Dómine, oblata sanctífica: et corda nostra Sancti Spíritus illustratióne emúnda."},{"k":"macro","name":"Per Dominum eiusdem"}],"Communio":[{"k":"ref","la":"Acts 2:2 2:4"},{"k":"text","la":"Factus est repénte de cœlo sonus tamquam adveniéntis spíritus veheméntis, ubi erant sedéntes, allelúja: et repléti sunt omnes Spíritu Sancto, loquéntes magnália Dei, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Sancti Spíritus, Dómine, corda nostra mundet infúsio: et sui roris íntima aspersióne fecúndet."},{"k":"macro","name":"Per Dominum eiusdem"}]},"hr":{"5974381bae9f3f59":{"t":"Mudr 1, 7, Ps 67, 2\n(Mudr 1, 7) Duh Gospodnji napuni svemir, <i>aleluja</i>!\nOn koji sve obuhvaća, poznaje svaki govor, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 67, 2) Nek ustane Bog i neka se rasprše njegovi neprijatelji! I neka bježe od njegova lica svi koji ga mrze.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Mudr 1, 7) Duh Gospodnji napuni svemir, <i>aleluja</i>!\nOn koji sve obuhvaća, poznaje svaki govor, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Mudr. 1, 7). Duh Gospodnji napunja svemir, Aleluja; i onaj, koji sve obuhvaća, čuje svaku riječ, Aleluja, Aleluja, Aleluja. (Ps. 67, 2) Nek ustane Bog i nek se razaspu neprijatelji njegovi i neka pobjegnu od lica njegova, koji mrze na nj. Slava Ocu . . . Duh Gospodnji, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 340–341 (snimka 171) (OCR)"},"221af66c071bf77a":{"t":"<i>Pomolimo se</i>.\nBože, koji si na današnji dan svjetlošću Duha Svetoga poučio srca vjernih, daj da u tom istom Duhu što je pravo spoznamo i njegovoj se utjehi vazda radujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si današnji dan svjetlošću Svetoga Duha poučio srca vjernih daj, da u istom Duhovi Duhu što je pravo mislimo i njegovoj se utjehi vazda radujemo. Po Gospodinu našem ... u jedinstvu istoga Duha . . .","knRef":"Kniewald 1942, str. 340–341 (snimka 171) (OCR)"},"c9946afa6840b238":{"t":"Dj 8, 5-8\nČitanje Djela apostolskih. U one dane Filip siđe u grad Samariju i stade im propovijedati Krista. Narod je pazio jednodušno na ono što je govorio Filip, slušajući i gledajući znakove što ih je činio; jer su nečisti duhovi izlazili s velikom vikom iz mnogih opsjednutih. I mnogi uzeti i hromi ozdraviše. I bila je velika radost u onome gradu.","kn":"Čitanje Djela apostolskih (8, 5-9). U one dane Filip siđe u grad Samariju i stade im propovijedati Kri- fita. Narod je pazio jednodušno na ono, što je govorio Filip, slušajući i gledajući znakove, što ih je činiO', jei su nečisti duhovi izlazili s velikorn vikom iz mnogih opsjednutih. I mnogi uzeti i hromi ozdraviše. I posta velika radost u gradu onome.","knRef":"Kniewald 1942, str. 350–351 (snimka 176) (OCR)"},"3fa7ac0c6379c5a5":{"t":"Ps 103, 30\n<i>Aleluja</i>, <i>aleluja</i>.\nPošalji Duha svojega i postat će novi svijet i obnovit ćeš lice zemlje, <i>aleluja</i>.\n[Ovdje se poklekne] Dođi, Duše Sveti, napuni srca svojih vjernika i zapali u njima oganj svoje ljubavi."},"8986d237bd5894a0":{"t":"Dođi, duše presveti, /Sa neba nas posjeti /Zrakom svoje milosti. <i>\n</i>\nDođi, Oče ubogih,/Djelitelju dara svih,/Dođi, srca svjetlosti. <i>\n</i>\nTješitelju tako blag, /Ti nebeski Goste drag, /Pun miline hlade tih. <i>\n</i>\nUmornima odmore,/U vrućini lahore,/Razgovore žalosnih. <i>\n</i>\nSjaju svjetla blaženog,/Sjaj u srcu puka svog,/Napuni nam dušu svu. <i>\n</i>\nBez božanstva tvojega /Svi smo mi bez ičega,/Tonemo u crnom zlu. <i>\n</i>\nNečiste nas umivaj,/Suha srca zalivaj, /Vidaj rane ranjenim. <i>\n</i>\nMekšaj ćudi kamene,/ Zagrij grudi ledene,/Ne daj nama putem zlim. <i>\n</i>\nSvim što vjeru imaju,/Što se u te ufaju, /Sedam svojih dara daj. <i>\n</i>\nDaj nam krepost zaslužnu/I smrt lijepu, blaženu,/Daj vjekovit svima raj. <i>\n</i>\n<i>amen</i>, <i>aleluja</i>."},"35e275d3f84c3385":{"t":"Lk 9, 1-6\nSlijedi sveto Evanđelje po Luki. U ono vrijeme sazvavši Isus dvanaestoricu dade im silu i vlast nad svim đavlima i da liječe bolesti. I posla ih da propovijedaju kraljevstvo Božje i da iscjeljuju bolesnike. I reče im: Ništa ne uzimajte na put, ni štapa, ni torbe, ni kruha, ni novaca, niti imajte po dvije haljine. I u koju god kuću uđete, ondje ostanite i odanle ne izlazite. I gdje vas ne prime, izlazeći iz onoga grada, otresite prah sa svojih nogu za svjedočanstvo protiv njih. Izišli su i prolazili po selima propovijedajući Evanđelje i svuda liječili.","kn":"t Slijedi sv. evanđelje po Luki (9. 1-6). U ono vrijeme sazvavši Isus dvanaestoricu dade im silu i vlast naid svim davlima i da liječe bolest. I posla ih da ipropovijedaju kraljevstvo Božje i da iscjeljuju bolesnike. I reče im: Ništa ne uzimajte ma put, ni štapa, ni torbe, ni kruha, ni novaca, niti imajte po dvije haljine. I u koju god kuću uđete, ondje ostanite, 1 odanle ne izlazite. I gdje vas ne prime, izlazeći iz onoga grada, otresite prah sa svojih nogu za svjedočanstvo protiv njih. Izišli su i prolazili po selima pripovijedajući evanđelje i svuda liječeći.","knRef":"Kniewald 1942, str. 352–353 (snimka 177) (OCR)"},"abc4ed74aaf19369":{"t":"Ps 67, 29-30\nUtvrdi ovo, Bože, što si učinio u nama! U svetom hramu tvojem, koji je u Jeruzalemu, kraljevi će ti donositi darove, <i>aleluja</i>.","kn":"(Ps. 67, 29, 30). Utvrdi, Bože, što si djelovao u nama; neka dođu kraljevi i prinesu Ti darove u Tvojem hramu u svetomu gradu, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 344–345 (snimka 173) (OCR)"},"8a23e3366dd2990d":{"t":"Posveti, molimo, Gospodine, prinesene darove a naša srca očisti svjetlošću Duha Svetoga.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, posveti prikazane darove 1 očisti naša srca prosviječenjem Duha Svetoga, po G. n, I. K.","knRef":"Kniewald 1942, str. 344–345 (snimka 173) (OCR)"},"e36be14714c3ff04":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. On uziđe nad sva nebesa, sjede uz tvoju desnu, te obećanog Duha Svetoga na današnji dan izli na posinjenu djecu. – Stoga sav svijet na krugu zemaljskom kliče zanosnom radošću, a i višnje sile i s njima anđeoske vlasti zajedno pjevaju pjesmu tvoje slave govoreći bez prestanka:","kn":"Predslovlje: Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi. Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospodinu našem, koji je uzašao nad sva nebesa i sjeo s desne Tvoje i na današnji dan izlio obećanoga Duha Svetoga na Božje posinke. Zato kliče čitav svijet i svemir pun veselja. A i višnje moći i anđeoske vlasti pjevaju pjesmu Tvoje slave govoreći bez prestanka:","knRef":"Kniewald 1942, str. 344–345 (snimka 173) (OCR)"},"6f9359f735e1fb70":{"t":"Dj 2, 2 i 4\nUjedanput ču se buka s neba, kao kad puše silan vjetar, gdje su bili, <i>aleluja</i>.\nI svi se napune Duha Svetoga i stadoše veličati djela Božja, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Dj. ap. 2, 2, 4). Najedamput postade šum s neba kao da puše silan vjetar i napuni svu kuću. gdje su sjedili, Aleluja; i napuniše se svi Duha Svetoga naviještajući veličanstvena djela Božja. Aleluja, Aleluja.","knRef":"Kniewald 1942, str. 344–345 (snimka 173) (OCR)"},"0ed7897a863e81f5":{"t":"<i>Pomolimo se</i>.\nSrca naša, Gospodine, očistio dolazak Duha Svetoga i oplodio ih svojom nutarnjom rosom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, da dolazak Duha Svetoga očisti naša srca i oplodi ih nutarnjom blagošću svoje rose. Po G. n. I. K. ... u jedinstvu istoga Duha . . .","knRef":"Kniewald 1942, str. 340–341 (snimka 171) (OCR)"}}});
